ff','buying.view'),('staff','categories.view'),('staff','customers.manage'),('staff','customers.view'),('staff','fulfilment.manage'),('staff','fulfilment.view'),('staff','inventory.manage'),('staff','inventory.view'),('staff','messaging.manage'),('staff','messaging.view'),('staff','notification.view'),('staff','offers.manage'),('staff','offers.view'),('staff','orders.manage'),('staff','orders.view'),('staff','returns.manage'),('staff','returns.view'),('staff','selling.manage'),('staff','selling.view'),('staff','tenant.view'),('staff','valuation.view')) v(role_code,permission_code) join public.roles r on r.code=v.role_code join public.permissions p on p.code=v.permission_code on conflict do nothing;
insert into public.plan_features(plan_id,feature_code,enabled,config) select pl.id,v.feature_code,v.enabled,v.config::jsonb from (values ('catalogue.pre_filled',true,'{"product_limit":null,"category_limit":null,"subcategory_limit":null}'),('module.analytics',false,'{}'),('module.audit',false,'{}'),('module.buying',true,'{}'),('module.customer_portal',true,'{}'),('module.fulfilment',true,'{}'),('module.integrations',false,'{}'),('module.inventory',true,'{}'),('module.market_intelligence',true,'{}'),('module.offers',true,'{}'),('module.orders',true,'{}'),('module.selling',true,'{}'),('module.staff',false,'{"staff_limit":10}'),('module.staff_messaging',false,'{}'),('module.storefront',true,'{}'),('module.trade_in',true,'{}'),('module.valuation',true,'{"methods":["manual","rule"]}'),('website.editor',true,'{"logo_upload":true,"image_content":true,"colour_selection":true,"custom_categories":true,"template_selection":true,"custom_subcategories":true}'),('website.preview',true,'{}'),('website.publish',true,'{}')) v(feature_code,enabled,config) join public.plans pl on pl.code='enhanced' on conflict(plan_id,feature_code) do update set enabled=excluded.enabled,config=excluded.config,updated_at=now();
